{
  "name": "fixture_export",
  "description": "Save a capture into [module/]src/test/resources/dt-fixtures/<name>: per-DB schema/data/constraints SQL + JSON, Kafka JSONL/schema/offsets, hashed manifest and loading instructions. Existing fixtures are preserved unless overwrite=true. Generated resources can be committed with tests.",
  "group": "code",
  "origin": "built-in",
  "execution": {
    "protocol": "dt.tool/v1",
    "transport": "in-process"
  },
  "inputSchema": {
    "type": "object",
    "properties": {
      "workspace": {
        "type": "string",
        "description": "Writable workspace id"
      },
      "capture": {
        "type": "string",
        "description": "Capture id"
      },
      "name": {
        "type": "string",
        "description": "Scenario name"
      },
      "directory": {
        "type": "string",
        "description": "Optional resource directory (for a multi-module project)"
      },
      "overwrite": {
        "type": "boolean",
        "default": false,
        "description": "Replace this fixture if it exists"
      }
    },
    "required": [
      "workspace",
      "capture"
    ]
  }
}
